bool JitHostHasLseAtomics() {
#if defined(__ANDROID__) && defined(__aarch64__) && defined(HWCAP_ATOMICS)
    static const bool supported = (getauxval(AT_HWCAP) & HWCAP_ATOMICS) != 0;
    return supported;
#else
    return false;
#endif
}

bool JitBlockUsesDirectFaultSlotV10(const LsxDecodedRegion& block) {
    return std::ranges::any_of(block.instructions, [](const LsxDecodedOp& ir) {
        const auto mnemonic = static_cast<X86Mnemonic>(ir.mnemonic);
        if (mnemonic != X86_MNEMONIC_LEA) {
            for (std::uint8_t index = 0; index < ir.operand_count; ++index) {
                const LsxOperandRecord& operand = ir.operands[index];
                if (operand.type == X86_OPERAND_TYPE_MEMORY &&
                    (operand.actions & (X86_OPERAND_ACTION_MASK_READ |
                                        X86_OPERAND_ACTION_MASK_WRITE)) != 0) {
                    return true;
                }
            }
        }
        switch (mnemonic) {
        case X86_MNEMONIC_PUSH:
        case X86_MNEMONIC_POP:
            [[fallthrough]];
        case X86_MNEMONIC_LEAVE:
        case X86_MNEMONIC_CALL:
        case X86_MNEMONIC_RET:
        case X86_MNEMONIC_PUSHF:
        case X86_MNEMONIC_PUSHFD:
        case X86_MNEMONIC_PUSHFQ:
        case X86_MNEMONIC_POPF:
        case X86_MNEMONIC_POPFD:
        case X86_MNEMONIC_POPFQ:
        case X86_MNEMONIC_MASKMOVDQU:
        case X86_MNEMONIC_VMASKMOVDQU:
        case X86_MNEMONIC_MOVSB:
        case X86_MNEMONIC_MOVSW:
        case X86_MNEMONIC_MOVSD:
        case X86_MNEMONIC_MOVSQ:
        case X86_MNEMONIC_STOSB:
        case X86_MNEMONIC_STOSW:
        case X86_MNEMONIC_STOSD:
            [[fallthrough]];
        case X86_MNEMONIC_STOSQ:
        case X86_MNEMONIC_CMPSB:
        case X86_MNEMONIC_CMPSW:
        case X86_MNEMONIC_CMPSD:
        case X86_MNEMONIC_CMPSQ:
            return true;
        default:
            return false;
        }
    });
}

bool JitBlockUsesInlineLseXchgV11(const LsxDecodedRegion& block) {
    return JitHostHasLseAtomics() &&
           std::ranges::any_of(block.instructions, [](const LsxDecodedOp& ir) {
               if (static_cast<X86Mnemonic>(ir.mnemonic) != X86_MNEMONIC_XCHG ||
                   ir.operand_count != 2) {
                   return false;
               }
               const bool lhs_memory =
                   ir.operands[0].type == X86_OPERAND_TYPE_MEMORY;
               const bool rhs_memory =
                   ir.operands[1].type == X86_OPERAND_TYPE_MEMORY;
               const auto& memory_operand =
                   lhs_memory ? ir.operands[0] : ir.operands[1];
               return (lhs_memory != rhs_memory) && memory_operand.size == 8;
           });
}

bool JitBlockUsesDirectLseXchgV12(const LsxDecodedRegion& block) {
    return JitBlockUsesInlineLseXchgV11(block);
}

bool JitBlockUsesScalarLogicDirectV14(const LsxDecodedRegion& block) {
    return std::ranges::any_of(block.instructions, [](const LsxDecodedOp& ir) {
        const auto mnemonic = static_cast<X86Mnemonic>(ir.mnemonic);
        if (mnemonic == X86_MNEMONIC_ANDN) {
            return true;
        }
        if (mnemonic != X86_MNEMONIC_TEST) {
            return false;
        }
        return std::ranges::any_of(
            std::span{ir.operands.data(), static_cast<std::size_t>(ir.operand_count)},
            [](const LsxOperandRecord& operand) {
                return operand.type == X86_OPERAND_TYPE_REGISTER &&
                       operand.reg.value >= X86_REGISTER_AH &&
                       operand.reg.value <= X86_REGISTER_BH;
            });
    });
}

bool IsJitVpslldImmDirectV15Instruction(const LsxDecodedOp& ir) {
    if (static_cast<X86Mnemonic>(ir.mnemonic) != X86_MNEMONIC_VPSLLD ||
        ir.decoded.encoding != X86_INSTRUCTION_ENCODING_VEX ||
        (ir.decoded.attributes &
         (X86_ATTRIB_HAS_LOCK | X86_ATTRIB_HAS_REP | X86_ATTRIB_HAS_REPE |
          X86_ATTRIB_HAS_REPNE)) != 0 ||
        ir.operand_count != 3 ||
        ir.operands[2].type != X86_OPERAND_TYPE_IMMEDIATE ||
        ir.operands[2].size != 8) {
        return false;
    }
    const auto vector_register_width = [](const LsxOperandRecord& operand) {
        if (operand.type != X86_OPERAND_TYPE_REGISTER) {
            return std::uint32_t{0};
        }
        if (operand.reg.value >= X86_REGISTER_XMM0 &&
            operand.reg.value <= X86_REGISTER_XMM15) {
            return std::uint32_t{128};
        }
        if (operand.reg.value >= X86_REGISTER_YMM0 &&
            operand.reg.value <= X86_REGISTER_YMM15) {
            return std::uint32_t{256};
        }
        return std::uint32_t{0};
    };
    const std::uint32_t width = vector_register_width(ir.operands[0]);
    if ((width != 128 && width != 256) || ir.operands[0].size != width ||
        ir.operands[1].size != width) {
        return false;
    }
    if (ir.operands[1].type == X86_OPERAND_TYPE_MEMORY) {
        return true;
    }
    return vector_register_width(ir.operands[1]) == width;
}

bool JitBlockUsesVpslldImmDirectV15(const LsxDecodedRegion& block) {
    return std::ranges::any_of(block.instructions,
                               IsJitVpslldImmDirectV15Instruction);
}

void WriteJitLogRecord(const char* format, va_list arguments) {
#ifdef __ANDROID__
    __android_log_vprint(
        ANDROID_LOG_INFO, "LSX4Native", format, arguments);
#else
    std::vfprintf(stderr, format, arguments);
    constexpr std::array line_end{'\n'};
    std::fwrite(line_end.data(), sizeof(char), line_end.size(), stderr);
    std::fflush(stderr);
#endif
}

bool JitBlockUsesInsertPsDirectV17(const LsxDecodedRegion& block) {
    return std::ranges::any_of(block.instructions, [](const LsxDecodedOp& ir) {
        const auto mnemonic = static_cast<X86Mnemonic>(ir.mnemonic);
        return mnemonic == X86_MNEMONIC_INSERTPS ||
               mnemonic == X86_MNEMONIC_VINSERTPS;
    });
}

bool JitBlockUsesDirectRetV18(const LsxDecodedRegion& block) {
    return !block.instructions.empty() &&
           static_cast<X86Mnemonic>(block.instructions.back().mnemonic) ==
               X86_MNEMONIC_RET;
}

bool JitBlockUsesHotStateDirectV19(const LsxDecodedRegion& block) {
    return std::ranges::any_of(block.instructions, [](const LsxDecodedOp& ir) {
        switch (static_cast<X86Mnemonic>(ir.mnemonic)) {
        case X86_MNEMONIC_FNSTENV:
        case X86_MNEMONIC_FLDENV:
        case X86_MNEMONIC_CVTPD2PS:
        case X86_MNEMONIC_CVTPS2PD:
        case X86_MNEMONIC_VCVTPD2PS:
        case X86_MNEMONIC_VCVTPS2PD:
            return true;
        default:
            return false;
        }
    });
}

bool JitBlockUsesHotAtomicPermuteV20(const LsxDecodedRegion& block) {
    return std::ranges::any_of(block.instructions, [](const LsxDecodedOp& ir) {
        const auto mnemonic = static_cast<X86Mnemonic>(ir.mnemonic);
        return mnemonic == X86_MNEMONIC_VPERMILPD ||
               (mnemonic == X86_MNEMONIC_DEC &&
                (ir.decoded.attributes & X86_ATTRIB_HAS_LOCK) != 0);
    });
}

void JitLog(const char* fmt, ...) {
    va_list arguments;
    va_start(arguments, fmt);
    WriteJitLogRecord(fmt, arguments);
    va_end(arguments);
}

constexpr unsigned long long LogU64(const std::uint64_t value) noexcept {
    return static_cast<unsigned long long>(value);
}

constexpr int LogBool(const bool value) noexcept {
    return value ? 1 : 0;
}

class DiagnosticSwitch {
public:
    constexpr DiagnosticSwitch(const char* marker_file,
                               const char* environment_variable) noexcept
        : marker_file_(marker_file), environment_variable_(environment_variable) {}

    bool Enabled() const {
#ifdef __ANDROID__
        int value = cached_.load(std::memory_order_relaxed);
        if (value == kUnknown) {
            value = access(marker_file_, F_OK) == 0 ? kEnabled : kDisabled;
            cached_.store(value, std::memory_order_relaxed);
        }
        return value == kEnabled;
#else
        return std::getenv(environment_variable_) != nullptr;
#endif
    }

private:
    static constexpr int kUnknown = -1;
    static constexpr int kDisabled = 0;
    static constexpr int kEnabled = 1;
    const char* marker_file_;
    const char* environment_variable_;
    mutable std::atomic<int> cached_{kUnknown};
};

