class ScopedJitSelfTestDifferential {
public:
    ScopedJitSelfTestDifferential()
        : previous_(g_jit_selftest_differential_active) {
        g_jit_selftest_differential_active = true;
    }

    ~ScopedJitSelfTestDifferential() {
        g_jit_selftest_differential_active = previous_;
    }

    ScopedJitSelfTestDifferential(const ScopedJitSelfTestDifferential&) = delete;
    ScopedJitSelfTestDifferential& operator=(
        const ScopedJitSelfTestDifferential&) = delete;

private:
    bool previous_{};
};

class ScopedJitSelfTestProductionDirect {
public:
    ScopedJitSelfTestProductionDirect()
        : previous_(g_jit_selftest_production_direct_active) {
        g_jit_selftest_production_direct_active = true;
    }

    ~ScopedJitSelfTestProductionDirect() {
        g_jit_selftest_production_direct_active = previous_;
    }

    ScopedJitSelfTestProductionDirect(
        const ScopedJitSelfTestProductionDirect&) = delete;
    ScopedJitSelfTestProductionDirect& operator=(
        const ScopedJitSelfTestProductionDirect&) = delete;

private:
    bool previous_{};
};

bool JitLiveCheckedNativeEnabled() {
    static const bool explicitly_enabled =
        JitAlwaysCheckEnabled() || JitDiagAlwaysCheckEnabled();
    if (g_jit_selftest_production_direct_active) {
        return false;
    }
    return g_jit_selftest_differential_active || explicitly_enabled;
}

struct JitStoreWatchRange {
    std::uint64_t lo = 0;
    std::uint64_t hi = 0;
    std::uint64_t object_vtable = 0;
    std::uint32_t field_offset = 0;
    std::uint32_t alternate_field_offset = 0;

    [[nodiscard]] bool Enabled() const noexcept {
        return hi > lo;
    }
};

const JitStoreWatchRange& JitDiagnosticStoreWatchRange() {
    static const JitStoreWatchRange range = [] {
        JitStoreWatchRange result;
#ifdef __ANDROID__
        const char* lo = std::getenv("EXECUTOR_DIAG_STORE_WATCH_LO");
        const char* hi = std::getenv("EXECUTOR_DIAG_STORE_WATCH_HI");
        if (lo != nullptr && hi != nullptr) {
            result.lo = std::strtoull(lo, nullptr, 0);
            result.hi = std::strtoull(hi, nullptr, 0);
        }
        if (const char* object_vtable =
                std::getenv("EXECUTOR_DIAG_STORE_WATCH_OBJECT_VTABLE")) {
            result.object_vtable = std::strtoull(object_vtable, nullptr, 0);
        }
        if (const char* field_offset =
                std::getenv("EXECUTOR_DIAG_STORE_WATCH_FIELD_OFFSET")) {
            result.field_offset =
                static_cast<std::uint32_t>(std::strtoul(field_offset, nullptr, 0));
        }
        if (const char* alternate_field_offset =
                std::getenv("EXECUTOR_DIAG_STORE_WATCH_ALTERNATE_FIELD_OFFSET")) {
            result.alternate_field_offset =
                static_cast<std::uint32_t>(std::strtoul(alternate_field_offset, nullptr, 0));
        }
#endif
        return result;
    }();
    return range;
}

void JitReportWatchedStore(const std::uint64_t guest_rip, const std::uint64_t address,
                           const std::uint64_t size_bytes,
                           const LsxMachineImage* const state) {
#ifdef __ANDROID__
    static std::atomic<std::uint64_t> ordinal{0};
    const std::uint64_t current = ordinal.fetch_add(1, std::memory_order_relaxed) + 1;
    std::array<std::uint8_t, 16> bytes{};
    const std::size_t copied =
        std::min<std::size_t>(bytes.size(), static_cast<std::size_t>(size_bytes));
    if (copied != 0) {
        std::memcpy(bytes.data(), reinterpret_cast<const void*>(address), copied);
    }
    std::uint64_t low = 0;
    std::uint64_t high = 0;
    std::memcpy(&low, bytes.data(), sizeof(low));
    std::memcpy(&high, bytes.data() + sizeof(low), sizeof(high));
    std::uint64_t object_base = 0;
    std::uint64_t object_parent = 0;
    std::uint64_t object_resource = 0;
    std::uint32_t object_resource_id = 0;
    const std::uint64_t guest_rax =
        state != nullptr ? ReadGuestGpr64(*state, LsxGpr::Rax) : 0;
    const std::uint64_t guest_r14 =
        state != nullptr ? ReadGuestGpr64(*state, LsxGpr::R14) : 0;
    const std::uint64_t guest_r15 =
        state != nullptr ? ReadGuestGpr64(*state, LsxGpr::R15) : 0;
    const auto& watch = JitDiagnosticStoreWatchRange();
    const auto try_object_base = [&](const std::uint32_t field_offset) {
        if (address < field_offset) {
            return false;
        }
        const std::uint64_t candidate = address - field_offset;
        std::uint64_t vtable = 0;
        std::memcpy(&vtable, reinterpret_cast<const void*>(candidate), sizeof(vtable));
        if (vtable != watch.object_vtable) {
            return false;
        }
        object_base = candidate;
        std::memcpy(&object_parent, reinterpret_cast<const void*>(candidate + 0x60),
                    sizeof(object_parent));
        std::memcpy(&object_resource, reinterpret_cast<const void*>(candidate + 0x68),
                    sizeof(object_resource));
        std::memcpy(&object_resource_id, reinterpret_cast<const void*>(candidate + 0x70),
                    sizeof(object_resource_id));
        return true;
    };
    if (watch.object_vtable != 0 && !try_object_base(watch.field_offset) &&
        watch.alternate_field_offset != watch.field_offset) {
        try_object_base(watch.alternate_field_offset);
    }
    JitLog("[EXECUTOR_JIT_STORE_WATCH] n=%llu rip=0x%llx addr=0x%llx bytes=%llu "
                "valueLo=0x%016llx valueHi=0x%016llx object=0x%llx parent=0x%llx "
                "resource=0x%llx resourceId=0x%x rax=0x%llx r14=0x%llx r15=0x%llx",
                static_cast<unsigned long long>(current),
                static_cast<unsigned long long>(guest_rip),
                static_cast<unsigned long long>(address),
                static_cast<unsigned long long>(size_bytes),
                static_cast<unsigned long long>(low),
                static_cast<unsigned long long>(high),
                static_cast<unsigned long long>(object_base),
                static_cast<unsigned long long>(object_parent),
                static_cast<unsigned long long>(object_resource), object_resource_id,
                static_cast<unsigned long long>(guest_rax),
                static_cast<unsigned long long>(guest_r14),
                static_cast<unsigned long long>(guest_r15));
#else
    (void)guest_rip;
    (void)address;
    (void)size_bytes;
    (void)state;
#endif
}

bool JitForceInterpretRip(std::uint64_t rip) {
#ifdef __ANDROID__
    struct InterpretationWindow {
        std::uint64_t first{};
        std::uint64_t past_last{};
        std::string thread_name;

        static InterpretationWindow FromEnvironment() {
            InterpretationWindow window;
            const auto read_number = [](const char* name) -> std::optional<std::uint64_t> {
                const char* text = std::getenv(name);
                if (text == nullptr || *text == '\0') {
                    return std::nullopt;
                }
                return std::strtoull(text, nullptr, 0);
            };
            const auto first = read_number("LSX4_TRANSLATION_INTERPRET_LO");
            const auto past_last = read_number("LSX4_TRANSLATION_INTERPRET_HI");
            if (first && past_last) {
                window.first = *first;
                window.past_last = *past_last;
            }
            if (const char* requested_thread =
                    std::getenv("LSX4_TRANSLATION_INTERPRET_THREAD")) {
                window.thread_name.assign(requested_thread);
            }
            return window;
        }
    };
    static const InterpretationWindow range = InterpretationWindow::FromEnvironment();
    if (range.past_last <= range.first ||
        !(rip >= range.first && rip < range.past_last)) {
        return false;
    }
    if (range.thread_name.empty()) {
        return true;
    }
    char name[64]{};
    return pthread_getname_np(pthread_self(), name, sizeof(name)) == 0 &&
           std::string_view{name}.find(range.thread_name) != std::string_view::npos;
#else
    (void)rip;
    return false;
#endif
}

template <typename T>
[[gnu::always_inline]] inline T LoadUnaligned(const void* ptr) {
    static_assert(std::is_trivially_copyable_v<T>);
    T value;
    T* const output = std::addressof(value);
    __builtin_memcpy(output, ptr, sizeof(value));
    return value;
}

template <typename T>
[[gnu::always_inline]] inline void StoreUnaligned(void* ptr, const T value) {
    static_assert(std::is_trivially_copyable_v<T>);
    const T* const source = std::addressof(value);
    __builtin_memcpy(ptr, source, sizeof(value));
}

