constexpr bool IsUnconditionalControlTransfer(
    const X86Mnemonic mnemonic) noexcept {
    return mnemonic == X86_MNEMONIC_JMP ||
           mnemonic == X86_MNEMONIC_CALL ||
           mnemonic == X86_MNEMONIC_RET;
}

constexpr bool IsGuestInstructionPointerRegister(
    const std::uint32_t reg) noexcept {
    return reg == X86_REGISTER_RIP || reg == X86_REGISTER_EIP;
}

constexpr std::uint64_t AlignGuestStackPointer(
    const std::uint64_t value) noexcept {
    return value & ~UINT64_C(15);
}

constexpr bool IsNativeScalarWidth(const std::uint32_t width) noexcept {
    return width == 8 || width == 16 || width == 32 || width == 64;
}

constexpr bool IsNativeVectorWriteWidth(
    const std::uint32_t width) noexcept {
    return IsNativeScalarWidth(width) || width == 128 || width == 256;
}

constexpr bool IsDwordOrQword(const std::uint32_t width) noexcept {
    return width == 32 || width == 64;
}

constexpr bool IsWordDwordOrQword(const std::uint32_t width) noexcept {
    return width == 16 || IsDwordOrQword(width);
}

std::uint8_t ImmediateControlByte(const LsxDecodedOp& instruction,
                                  const std::size_t operand_index) {
    return static_cast<std::uint8_t>(
        instruction.operands[operand_index].imm.value.u);
}

constexpr std::uint64_t NextGuestInstruction(
    const LsxDecodedOp& instruction) noexcept {
    return instruction.guest_rip + instruction.length;
}

constexpr X86Mnemonic DecodedMnemonic(
    const LsxDecodedOp& instruction) noexcept {
    return static_cast<X86Mnemonic>(instruction.mnemonic);
}

constexpr bool EndsWithOpcode(const LsxDecodedOp& instruction,
                              const std::uint8_t opcode) noexcept {
    return instruction.length > 0 &&
           instruction.bytes[instruction.length - 1] == opcode;
}

