struct CheckedNativeBlockContext {
    struct ValidationState {
        std::atomic<std::uint32_t> completed{0};
        std::atomic<std::uint32_t> accepted{0};
        std::atomic<std::uint32_t> rejected{0};
    };

    CheckedNativeBlockContext(const LsxDecodedRegion* decoded,
                              const Arm64BlockEntry entry) noexcept
        : block(decoded), native(entry), validation_goal(static_cast<std::uint32_t>(
              std::max<std::size_t>(decoded != nullptr ? decoded->instructions.size() : 0,
                                    std::tuple_size_v<decltype(LsxMachineImage{}.gpr)>))) {}

    bool CompleteValidation() noexcept {
        const std::uint32_t completed =
            validation.completed.fetch_add(1, std::memory_order_relaxed) + 1;
        return completed >= validation_goal &&
               validation.accepted.exchange(1, std::memory_order_acq_rel) == 0;
    }

    [[nodiscard]] bool CanInvoke(const LsxMachineImage* machine) const noexcept {
        return machine != nullptr && block != nullptr && native != nullptr;
    }

    const LsxDecodedRegion* block = nullptr;
    Arm64BlockEntry native = nullptr;
    ValidationState validation{};
    std::uint32_t validation_goal = 1;
};

static_assert(std::atomic<std::uint32_t>::is_always_lock_free);
static_assert(offsetof(CheckedNativeBlockContext, native) == 8);
static_assert(offsetof(CheckedNativeBlockContext, validation) +
                  offsetof(CheckedNativeBlockContext::ValidationState, accepted) == 20);
static_assert(offsetof(CheckedNativeBlockContext, validation) +
                  offsetof(CheckedNativeBlockContext::ValidationState, rejected) == 24);

