                            code->sub(code->x5, code->x14, watch.field_offset);
                            code->ldr(code->x5, Xbyak_aarch64::ptr(code->x5));
                            code->mov(code->x6, watch.object_vtable);
                            code->cmp(code->x5, code->x6);
                            code->b(Xbyak_aarch64::EQ, object_field_matches);
