                        break;
                    case 16:
                        code->strh(word, Xbyak_aarch64::ptr(address));
                        break;
                    case 32:
                        code->str(word, Xbyak_aarch64::ptr(address));
                        break;
                    case 64:
                        code->str(value, Xbyak_aarch64::ptr(address));
                        break;
                    default:
