                            code->ins(code->v5.d2[0], code->x10);
                            code->mov(code->x10, mask_words[3]);
                            code->ins(code->v5.d2[1], code->x10);
                            code->bsl(code->v5.b16, code->v3.b16, code->v1.b16);
