                        std::uint64_t mask_high = 0;
                        std::memcpy(&mask_low, blend_mask.data(), sizeof(mask_low));
                        std::memcpy(&mask_high, blend_mask.data() + 4, sizeof(mask_high));
                        code->eor(code->v4.b16, code->v4.b16, code->v4.b16);
                        code->mov(code->x10, mask_low);
                        code->ins(code->v4.d2[0], code->x10);
                        code->mov(code->x10, mask_high);
                        code->ins(code->v4.d2[1], code->x10);
                        code->bsl(code->v4.b16, code->v2.b16, code->v0.b16);
                        emitted = emit_vector_store_pair(ir, ir.operands[0], code->q4,
                                                         code->q1, 16);
                        emitted_simd_fast += emitted ? 1u : 0u;
