                        std::uint32_t size_bits = 0;
                        emitted = is_native_memory_xadd(ir) &&
                                  register_state_offset(
                                      register_operand.reg.value,
                                      state_offset, size_bits) &&
                                  emit_memory_address(
                                      ir, memory_operand, code->x14);
