bool IsVectorInsertElementMnemonic(const X86Mnemonic mnemonic) {
    const auto plan = PlanElementTransfer(mnemonic);
    return plan && plan->direction == ElementTransferDirection::Insert;
}

bool IsVexVectorInsertElementMnemonic(const X86Mnemonic mnemonic) {
    const auto plan = PlanElementTransfer(mnemonic);
    return plan && plan->direction == ElementTransferDirection::Insert &&
           plan->distinct_merge_operand;
}

std::size_t VectorInsertExtractElementBytes(const X86Mnemonic mnemonic) {
    const auto plan = PlanElementTransfer(mnemonic);
    return plan ? plan->element_bytes : 0u;
}

bool IsVectorExtractElementMnemonic(const X86Mnemonic mnemonic) {
    const auto plan = PlanElementTransfer(mnemonic);
    return plan && plan->direction == ElementTransferDirection::Extract;
}

