[[gnu::always_inline]] inline bool IsPackedReciprocalEstimateMnemonic(
    const X86Mnemonic mnemonic) {
    switch (mnemonic) {
    case X86_MNEMONIC_RCPPS:
    case X86_MNEMONIC_RSQRTPS:
    case X86_MNEMONIC_VRCPPS:
    case X86_MNEMONIC_VRSQRTPS:
        return true;
    default:
        return false;
    }
}

[[gnu::always_inline]] inline bool IsVexPackedReciprocalEstimateMnemonic(
    const X86Mnemonic mnemonic) {
    return mnemonic == X86_MNEMONIC_VRCPPS ||
           mnemonic == X86_MNEMONIC_VRSQRTPS;
}

[[gnu::always_inline]] inline bool PackedReciprocalEstimateSqrt(
    const X86Mnemonic mnemonic) {
    return mnemonic == X86_MNEMONIC_RSQRTPS ||
           mnemonic == X86_MNEMONIC_VRSQRTPS;
}

bool IsStringCmpsInstruction(const LsxDecodedOp& ir) {
    const auto opcode =
        ir.length != 0
            ? std::optional<std::uint8_t>{ir.bytes[ir.length - 1]}
            : std::nullopt;
    if (!opcode) {
        return false;
    }
    const auto mnemonic = static_cast<X86Mnemonic>(ir.mnemonic);
    constexpr std::array encodings{
        std::pair{X86_MNEMONIC_CMPSB, std::uint8_t{0xa6}},
        std::pair{X86_MNEMONIC_CMPSW, std::uint8_t{0xa7}},
        std::pair{X86_MNEMONIC_CMPSD, std::uint8_t{0xa7}},
        std::pair{X86_MNEMONIC_CMPSQ, std::uint8_t{0xa7}},
    };
    return std::ranges::any_of(encodings, [&](const auto& encoding) {
        return encoding.first == mnemonic && encoding.second == *opcode;
    });
}

bool IsVectorImmediateBlendMnemonic(const X86Mnemonic mnemonic) {
    const auto plan = PlanVectorBlend(mnemonic);
    return plan && plan->control == BlendControlKind::Immediate;
}

bool IsVexVectorImmediateBlendMnemonic(const X86Mnemonic mnemonic) {
    const auto plan = PlanVectorBlend(mnemonic);
    return plan && plan->control == BlendControlKind::Immediate &&
           plan->distinct_left_operand;
}

std::size_t VectorImmediateBlendLaneBytes(const X86Mnemonic mnemonic) {
    const auto plan = PlanVectorBlend(mnemonic);
    return plan && plan->control == BlendControlKind::Immediate
               ? plan->lane_bytes
               : 0u;
}

bool IsVectorVariableBlendMnemonic(const X86Mnemonic mnemonic) {
    const auto plan = PlanVectorBlend(mnemonic);
    return plan && plan->control == BlendControlKind::VectorMask;
}

bool IsVexVectorVariableBlendMnemonic(const X86Mnemonic mnemonic) {
    const auto plan = PlanVectorBlend(mnemonic);
    return plan && plan->control == BlendControlKind::VectorMask &&
           plan->distinct_left_operand;
}

std::size_t VectorVariableBlendLaneBytes(const X86Mnemonic mnemonic) {
    const auto plan = PlanVectorBlend(mnemonic);
    return plan && plan->control == BlendControlKind::VectorMask
               ? plan->lane_bytes
               : 0u;
}

