        const bool repeat = (ir->decoded.attributes &
                             (X86_ATTRIB_HAS_REP | X86_ATTRIB_HAS_REPE |
                              X86_ATTRIB_HAS_REPNE)) != 0;
        CopyStringUnit(*state, element_size, repeat);
