    case X86_MNEMONIC_MOVSXD:
        transfer_scalar_operand(true);
        return 0;
    case X86_MNEMONIC_MOVZX:
        transfer_scalar_operand(false);
        return 0;
    case X86_MNEMONIC_LEA:
        ExecuteAddressFormation(*state, *ir);
