        const auto run_generic_scalar_case = [&]<typename Bytes, typename InitState>(
            const Bytes& bytes, const std::uint32_t max_instructions,
            const std::size_t expected_instruction_count, InitState init_state) {
            LsxDecodedRegion decoded = DecodeGuestBasicRegion(
                reinterpret_cast<std::uint64_t>(bytes.data()), max_instructions);
            Arm64BlockEntry native_direct = nullptr;
            Arm64BlockEntry native_entry =
                arena.EmitNativeControlFlowBlock(decoded, nullptr, &native_direct);
            bool has_guest_memory_access = false;
            for (const LsxDecodedOp& ir : decoded.instructions) {
                if (static_cast<X86Mnemonic>(ir.mnemonic) == X86_MNEMONIC_LEA) {
                    continue;
                }
                const auto operands =
                    std::span{ir.operands}.first(ir.operand_count);
                for (const auto& operand : operands) {
                    has_guest_memory_access |=
                        operand.type == X86_OPERAND_TYPE_MEMORY &&
                        (operand.actions & (X86_OPERAND_ACTION_MASK_READ |
                                            X86_OPERAND_ACTION_MASK_WRITE)) != 0;
                }
            }
            if (decoded.HasDecodeFailure() || !decoded.SupportsInitialNativeTier() ||
                decoded.instructions.size() != expected_instruction_count ||
                native_entry == nullptr ||
                (has_guest_memory_access ? native_direct == nullptr
                                         : native_direct != nullptr)) {
                return false;
            }

            const std::uint64_t trusted_before =
                g_jit_checked_native_trusted.load(std::memory_order_relaxed);
            bool matches = true;
            for (std::uint32_t iteration = 0; iteration < 18 && matches; ++iteration) {
                LsxMachineImage interpreter_state{};
                init_state(interpreter_state, iteration);
                LsxMachineImage native_state = interpreter_state;
                const std::uint64_t interpreter_result =
                    InterpretDecodedRegion(&interpreter_state, &decoded);
                const std::uint64_t native_result = native_entry(&native_state);
                matches = EffectiveBlockNext(decoded, interpreter_state, interpreter_result) ==
                              EffectiveBlockNext(decoded, native_state, native_result) &&
                          CheckedNativeStateMatches(native_state, interpreter_state);
            }
            const std::uint64_t trusted_after =
                g_jit_checked_native_trusted.load(std::memory_order_relaxed);
            return matches && (has_guest_memory_access
                ? trusted_after == trusted_before
                : trusted_after > trusted_before);
        };

